// Dane z webhooka są w $json.body - spłaszczamy je, żeby dalej używać $json.pole
const src = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const required = [];
const missing = required.filter((k) => src[k] === undefined || src[k] === null || String(src[k]).trim() === '');
if (missing.length) {
  throw new Error('Brak wymaganych pól: ' + missing.join(', '));
}
const clean = {};
for (const [k, v] of Object.entries(src)) {
  clean[k] = typeof v === 'string' ? v.trim().slice(0, 5000) : v;
}
if (clean.email !== undefined && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(clean.email))) {
  throw new Error('Niepoprawny adres e-mail');
}
return { json: { ...clean, _odebrano: new Date().toISOString() } };

// Weryfikacja podpisu X-Twilio-Signature (Twilio nie wysyła nagłówka Header Auth).
// Wymaga: NODE_FUNCTION_ALLOW_BUILTIN=crypto oraz zmiennej TWILIO_AUTH_TOKEN w środowisku n8n.
const crypto = require('crypto');
const token = $env.TWILIO_AUTH_TOKEN;
if (!token) throw new Error('Brak TWILIO_AUTH_TOKEN – odrzucam żądanie');
const url = $('Konfiguracja').first().json.publicznyUrlWebhooka;
const params = $json.body || {};
const data = url + Object.keys(params).sort().map((k) => k + params[k]).join('');
const expected = crypto.createHmac('sha1', token).update(Buffer.from(data, 'utf-8')).digest('base64');
const got = $json.headers?.['x-twilio-signature'] || '';
const ok = got.length === expected.length && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected));
if (!ok) throw new Error('Niepoprawny podpis Twilio');
return { json: { speech: String(params.SpeechResult || '').slice(0, 1000), callSid: params.CallSid || '' } };

const SYSTEM = "Jesteś uprzejmą recepcjonistką firmy rozmawiającą przez telefon. Odpowiadasz maks. 2 krótkimi zdaniami, po polsku, tylko na podstawie informacji o firmie. Jeśli nie wiesz – zaproponuj kontakt mailowy lub oddzwonienie.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"odpowiedz\": tekst do przeczytania}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Informacje o firmie:\n${$('Konfiguracja').first().json.informacjeOFirmie}\n\nKlient powiedział: ${$('Weryfikuj podpis Twilio').item.json.speech}`;
return {
  json: {
    ...$json,
    _aiPrompt: String(user).slice(0, 12000),
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (odpowiedź głosowa)').item.json };
delete ctx._aiPrompt;
let out = {};
let aiError = '';
try {
  const raw = $json.output ?? '';
  out = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"odpowiedz":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };

const esc = (s) => String(s).replace(/[<>&'"]/g, (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' }[c]));
const url = esc($('Konfiguracja').first().json.publicznyUrlWebhooka);
const say = esc($json._aiOk && $json.odpowiedz ? $json.odpowiedz + ' Czy mogę pomóc w czymś jeszcze?' : 'Przepraszam, mam chwilowy problem. Proszę napisać na nasz adres e-mail.');
return { json: { twiml: '<?xml version="1.0" encoding="UTF-8"?><Response><Gather input="speech" language="pl-PL" speechTimeout="auto" action="' + url + '" method="POST"><Say language="pl-PL">' + say + '</Say></Gather><Say language="pl-PL">Nie usłyszałem odpowiedzi. Do usłyszenia.</Say></Response>' } };

